mapper.select:
SELECT p.id, p.name, p.description, p.owner_id, p.revision, p.deleted, p.created_at, p.updated_at,


 ORDER BY p.created_at DESC, p.id DESC
 LIMIT #{offset}, #{size}

mapper.update:
UPDATE wb_project
   SET name = #{name},
       description = #{description},
       revision = revision + 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND revision = #{revision}
   AND deleted = 0

UPDATE wb_project
   SET owner_id = #{newOwnerId},
       revision = revision + 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND revision = #{revision}
   AND deleted = 0

UPDATE wb_project
   SET deleted = 1,
       revision = revision + 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND revision = #{revision}
   AND deleted = 0
